-- P1.2 — Tenant columns and composite uniques.
--
-- This file was generated by drizzle-kit and then REWRITTEN BY HAND, because the generated
-- form is only correct against an empty database.
--
-- What was wrong with the generated version
-- -----------------------------------------
-- It emitted fourteen statements of the form:
--
--     ALTER TABLE "messages" ADD COLUMN "organization_id" varchar(255) NOT NULL;
--
-- PostgreSQL rejects that outright on any table that already has rows: there is no default,
-- so the existing rows would violate NOT NULL immediately. Against the current (unprovisioned)
-- database it would have appeared to work, and it would have failed the first time it met real
-- data — which is exactly the class of "it compiled, therefore it works" this project is trying
-- to stop shipping.
--
-- What this version does instead
-- ------------------------------
-- The standard three phases: add the column nullable, backfill it, then enforce NOT NULL.
--
-- The backfill derives each row's tenant from its parent, so no row is assigned to a tenant on
-- the strength of a guess. Four tables have no parent to derive from — campaigns,
-- knowledge_items, attention_items and ai_run_logs — and for those the migration DELIBERATELY
-- STOPS and tells the operator to supply the value, rather than sweeping the rows into whatever
-- organisation happens to be first. Assigning a customer record to the wrong tenant is not a
-- lesser failure than aborting a migration.
--
-- Adding the uniques may also fail, and that failure is INFORMATION: it means duplicates
-- already exist that the missing constraints permitted. Resolve them before re-running; do not
-- weaken the constraint to make the migration pass.
--
-- Set the fallback organisation before running, if the parentless tables have rows:
--     \set migration_org_id 'your-org-id'
-- or edit the DO block below.

-- ---------------------------------------------------------------------------
-- 1. New table (no backfill needed).
-- ---------------------------------------------------------------------------
CREATE TABLE "campaign_recipients" (
	"id" varchar(255) PRIMARY KEY NOT NULL,
	"organization_id" varchar(255) NOT NULL,
	"campaign_id" varchar(255) NOT NULL,
	"contact_id" varchar(255) NOT NULL,
	"step_number" integer DEFAULT 0 NOT NULL,
	"status" varchar(50) DEFAULT 'ENROLLED' NOT NULL,
	"last_step_sent_at" timestamp,
	"next_step_due_at" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "campaign_recipients_org_campaign_contact_unique" UNIQUE("organization_id","campaign_id","contact_id")
);
--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 2. Drop the global uniques that tenancy replaces.
--
--    users.email was globally unique, which stops one person holding an account in two
--    organisations and turns "is this address taken?" into a probe for users in someone else's
--    tenant. outbox_messages.idempotency_key was globally unique, so one tenant's key could
--    suppress another tenant's send — a silent non-delivery that looks like deduplication.
-- ---------------------------------------------------------------------------
ALTER TABLE "outbox_messages" DROP CONSTRAINT IF EXISTS "outbox_messages_idempotency_key_unique";--> statement-breakpoint
ALTER TABLE "users" DROP CONSTRAINT IF EXISTS "users_email_unique";--> statement-breakpoint

