-- ---------------------------------------------------------------------------
ALTER TABLE "ai_run_logs" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "attention_items" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "campaigns" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "contacts" ADD COLUMN "email_key" varchar(255);--> statement-breakpoint
ALTER TABLE "conversation_facts" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "customer_commitments" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "knowledge_items" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "meetings" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "messages" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "objection_ledger" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "opportunities" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "outbox_messages" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "question_ledger" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint
ALTER TABLE "quote_snapshots" ADD COLUMN "organization_id" varchar(255);--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 4. Backfill from the parent row.
--
--    Each row's tenant is the tenant of the record it already belongs to. Nothing here
--    invents an association.
--
--    contacts.email_key mirrors server/lib/emailKey.ts: the address is taken out of any
--    display-name form, trimmed and lowercased. If the two ever disagree the constraint stops
--    meaning what it says, so they are changed together.
-- ---------------------------------------------------------------------------
UPDATE "contacts"
   SET "email_key" = lower(trim(
         CASE WHEN "primary_email" LIKE '%<%>%'
              THEN substring("primary_email" from '<([^<>]+)>')
              ELSE "primary_email"
         END))
 WHERE "email_key" IS NULL;--> statement-breakpoint

UPDATE "messages" m
   SET "organization_id" = c."organization_id"
  FROM "conversations" c
 WHERE m."conversation_id" = c."id" AND m."organization_id" IS NULL;--> statement-breakpoint

UPDATE "conversation_facts" f
   SET "organization_id" = c."organization_id"
  FROM "conversations" c
 WHERE f."conversation_id" = c."id" AND f."organization_id" IS NULL;--> statement-breakpoint

UPDATE "outbox_messages" o
   SET "organization_id" = c."organization_id"
  FROM "conversations" c
 WHERE o."conversation_id" = c."id" AND o."organization_id" IS NULL;--> statement-breakpoint

UPDATE "customer_commitments" x
   SET "organization_id" = c."organization_id"
  FROM "conversations" c
 WHERE x."conversation_id" = c."id" AND x."organization_id" IS NULL;--> statement-breakpoint

UPDATE "question_ledger" x
   SET "organization_id" = c."organization_id"
  FROM "conversations" c
 WHERE x."conversation_id" = c."id" AND x."organization_id" IS NULL;--> statement-breakpoint

UPDATE "objection_ledger" x
   SET "organization_id" = c."organization_id"
  FROM "conversations" c
 WHERE x."conversation_id" = c."id" AND x."organization_id" IS NULL;--> statement-breakpoint

