  FROM "contacts" c
 WHERE o."contact_id" = c."id" AND o."organization_id" IS NULL;--> statement-breakpoint

UPDATE "quote_snapshots" q
   SET "organization_id" = c."organization_id"
  FROM "contacts" c
 WHERE q."contact_id" = c."id" AND q."organization_id" IS NULL;--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 5. Refuse to guess.
--
--    campaigns, knowledge_items, attention_items and ai_run_logs have no parent that names a
--    tenant. If any of them holds rows, this migration stops. That is the intended behaviour:
--    the alternative is to assign one customer's campaign, knowledge or audit log to another
--    customer's organisation, silently and irreversibly, and a failed migration is recoverable
--    in a way that is not.
--
--    To proceed, set the organisation these rows belong to and re-run:
--        UPDATE campaigns SET organization_id = '<org>' WHERE organization_id IS NULL;
--    (likewise for knowledge_items, attention_items, ai_run_logs)
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  orphans record;
  total bigint := 0;
  detail text := '';
BEGIN
  FOR orphans IN
    SELECT 'campaigns' AS t, count(*) AS n FROM campaigns WHERE organization_id IS NULL
    UNION ALL SELECT 'knowledge_items', count(*) FROM knowledge_items WHERE organization_id IS NULL
    UNION ALL SELECT 'attention_items', count(*) FROM attention_items WHERE organization_id IS NULL
    UNION ALL SELECT 'ai_run_logs', count(*) FROM ai_run_logs WHERE organization_id IS NULL
    UNION ALL SELECT 'messages (orphaned)', count(*) FROM messages WHERE organization_id IS NULL
    UNION ALL SELECT 'conversation_facts (orphaned)', count(*) FROM conversation_facts WHERE organization_id IS NULL
    UNION ALL SELECT 'outbox_messages (orphaned)', count(*) FROM outbox_messages WHERE organization_id IS NULL
    UNION ALL SELECT 'meetings (orphaned)', count(*) FROM meetings WHERE organization_id IS NULL
    UNION ALL SELECT 'opportunities (orphaned)', count(*) FROM opportunities WHERE organization_id IS NULL
    UNION ALL SELECT 'quote_snapshots (orphaned)', count(*) FROM quote_snapshots WHERE organization_id IS NULL
    UNION ALL SELECT 'customer_commitments (orphaned)', count(*) FROM customer_commitments WHERE organization_id IS NULL
    UNION ALL SELECT 'question_ledger (orphaned)', count(*) FROM question_ledger WHERE organization_id IS NULL
    UNION ALL SELECT 'objection_ledger (orphaned)', count(*) FROM objection_ledger WHERE organization_id IS NULL
    UNION ALL SELECT 'contacts (no usable email)', count(*) FROM contacts WHERE email_key IS NULL
  LOOP
    IF orphans.n > 0 THEN
      total := total + orphans.n;
      detail := detail || format('  %s: %s row(s)%s', orphans.t, orphans.n, chr(10));
    END IF;
  END LOOP;

  IF total > 0 THEN
    RAISE EXCEPTION
      'P1.2 migration stopped: % row(s) have no derivable tenant.%s%sAssign them explicitly and re-run. Do NOT default them to an arbitrary organisation.',
      total, chr(10), detail;
  END IF;
END $$;--> statement-breakpoint

