-- ---------------------------------------------------------------------------
-- 9. The five required composite uniques, plus the two that tenancy rescoped.
--
--    A failure here is a finding, not an obstacle: it means the data already contains
--    duplicates that the absence of these constraints permitted — two contacts for one
--    person, one thread split across two conversations, an email ingested twice. Resolve the
--    duplicates; do not drop the constraint.
-- ---------------------------------------------------------------------------
ALTER TABLE "contacts" ADD CONSTRAINT "contacts_org_email_key_unique" UNIQUE("organization_id","email_key");--> statement-breakpoint
ALTER TABLE "conversations" ADD CONSTRAINT "conversations_org_thread_unique" UNIQUE("organization_id","provider_thread_id");--> statement-breakpoint
ALTER TABLE "messages" ADD CONSTRAINT "messages_org_provider_msg_unique" UNIQUE("organization_id","provider","provider_message_id");--> statement-breakpoint
ALTER TABLE "oauth_connections" ADD CONSTRAINT "oauth_org_provider_account_unique" UNIQUE("organization_id","provider","account_email");--> statement-breakpoint
ALTER TABLE "outbox_messages" ADD CONSTRAINT "outbox_org_idempotency_unique" UNIQUE("organization_id","idempotency_key");--> statement-breakpoint
ALTER TABLE "users" ADD CONSTRAINT "users_org_email_unique" UNIQUE("organization_id","email");
